//! SIMULATED art fixtures: drawn by code, never generated by a provider or
//! taken from a stream. The committed PNGs under tests/fixtures/simulated are
//! exactly these drawings (checked by `committed_fixtures_match_their_generator`).
#![allow(dead_code)]
use cc_beacons::art::raster::{Rgba, encode_png};

pub const FIXTURES: [&str; 4] = [
    "simulated-votebar.png",
    "simulated-frame.png",
    "simulated-beacon.png",
    "simulated-beacon-base.png",
];

fn rounded(x: i64, y: i64, (x0, y0, x1, y1): (i64, i64, i64, i64), r: i64) -> bool {
    if x < x0 || y < y0 || x >= x1 || y >= y1 {
        return false;
    }
    let cx = x.clamp(x0 + r, x1 - 1 - r);
    let cy = y.clamp(y0 + r, y1 - 1 - r);
    (x - cx).pow(2) + (y - cy).pow(2) <= r * r
}

/// 768x256 vote bar: gold/teal housing, dark navy track at (96,104)-(672,152),
/// corner radius 12 (track height 48: radius 0.25).
pub fn votebar() -> Rgba {
    let mut image = Rgba::transparent(768, 256).unwrap();
    for y in 0..256 {
        for x in 0..768 {
            let (xi, yi) = (i64::from(x), i64::from(y));
            if rounded(xi, yi, (96, 104, 672, 152), 12) {
                image.set(x, y, [14, 18, 34, 255]);
            } else if rounded(xi, yi, (48, 72, 720, 184), 28) {
                let gold = (x / 8 + y / 8) % 2 == 0;
                let colour = if gold {
                    [196, 150, 60, 255]
                } else {
                    [40, 150, 140, 255]
                };
                image.set(x, y, colour);
            }
        }
    }
    image
}

/// 768x432 facecam frame: 24px violet border, transparent window (24,24)-(744,408).
pub fn frame() -> Rgba {
    let mut image = Rgba::transparent(768, 432).unwrap();
    for y in 0..432 {
        for x in 0..768 {
            if !(24..744).contains(&x) || !(24..408).contains(&y) {
                image.set(x, y, [120, 60, 170, 255]);
            }
        }
    }
    image
}

/// Deterministic low-amplitude texture, like a generative re-render.
fn noise(x: u32, y: u32) -> u8 {
    ((x.wrapping_mul(31) ^ y.wrapping_mul(17)) % 7) as u8
}

/// 576x768 beacon: steel body with a cyan glowing core disc centred at
/// (288,330), radius 70. `with_core: false` is the effect-removed base, with
/// the faint texture shifted, as an edit call would return it.
pub fn beacon(with_core: bool) -> Rgba {
    let mut image = Rgba::transparent(576, 768).unwrap();
    for y in 0..768u32 {
        for x in 0..576u32 {
            let (xi, yi) = (i64::from(x), i64::from(y));
            if !rounded(xi, yi, (128, 120, 448, 700), 40) {
                continue;
            }
            let shade = noise(x + u32::from(!with_core), y);
            let mut pixel = [70 + shade, 76 + shade, 88 + shade, 255];
            let d2 = (xi - 288).pow(2) + (yi - 330).pow(2);
            if with_core && d2 <= 70 * 70 {
                pixel = [60, 240, 250, 255];
            }
            image.set(x, y, pixel);
        }
    }
    image
}

pub fn generate(name: &str) -> Vec<u8> {
    let image = match name {
        "simulated-votebar.png" => votebar(),
        "simulated-frame.png" => frame(),
        "simulated-beacon.png" => beacon(true),
        "simulated-beacon-base.png" => beacon(false),
        _ => panic!("unknown simulated fixture"),
    };
    encode_png(&image).unwrap()
}

pub fn path(name: &str) -> std::path::PathBuf {
    std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        // Shared with cc-core's tests: resolve through the crates directory.
        .join("../cc-beacons/tests/fixtures/simulated")
        .join(name)
}
